class StickyProductDetails extends HTMLElement{constructor(){super(),this.element=this.querySelector(".pdpMain__details"),this.topSpacer=document.getElementById("MainHeader").offsetHeight+24,this.lastScrollPosition=window.scrollY,this.currentScrollPosition=window.scrollY,this.elementDetails={},this.element&&(this.init(),document.addEventListener("resize",()=>this.recalculateHeights()),document.addEventListener("scroll",()=>this.updatePosition()))}init(){this.recalculateHeights(),this.updatePosition()}recalculateHeights(){this.viewportHeight=window.innerHeight,this.startPosition=this.parentElement.getBoundingClientRect().top+window.scrollY,this.endPosition=this.parentElement.offsetHeight+this.startPosition-this.viewportHeight,this.elementDetails={height:this.element.offsetHeight,position:this.elementDetails.hasOwnProperty("position")?this.elementDetails.position+"px":"0px"}}updatePosition(){this.currentScrollPosition=window.scrollY;const t=this.topSpacer+this.elementDetails.height-this.viewportHeight;let e=this.elementDetails.position;e+=this.currentScrollPosition-this.lastScrollPosition,e=this.currentScrollPosition<=this.startPosition?0:e,e=this.currentScrollPosition>this.endPosition?t:e,e=Math.abs(e)===e&&Math.abs(e)>t?t:e,e=Math.abs(e)!==e?0:e,this.elementDetails.position=e,this.element.style.top=`${this.topSpacer+-1*e}px`,this.lastScrollPosition=this.currentScrollPosition,this.element.offsetHeight!==this.elementDetails.height&&(this.elementDetails.height=this.element.offsetHeight)}}customElements.define("sticky-product-details",StickyProductDetails);